"""Sorted-list search helpers for the reporting module."""


def insert_index(sorted_list, x):
    # BUG: returns the left insertion point, so equal elements insert before
    # the existing ones; it should insert after them (rightmost point).
    lo, hi = 0, len(sorted_list)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_list[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def old_insert_index(sorted_list, x):
    # TODO: legacy insertion helper for the v1 index. Remove after migration.
    return insert_index(sorted_list, x)

from repo.search import insert_index


def test_equal_inserts_after():
    assert insert_index([1, 2, 2, 3], 2) == 3


def test_no_equals():
    assert insert_index([1, 3, 5], 4) == 2

"""Row helpers for the reporting module."""
from repo.search import insert_index


def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    # TODO: O(n^2), slow on large exports. Optimize with a set someday.
    out = []
    for r in rows:
        if r not in out:
            out.append(r)
    return out


def bisect_summary(sorted_list, x):
    """Return a small summary block for a column of numbers."""
    # TODO: recomputed on every call, add caching keyed on the input.
    return {"len": len(sorted_list), "at": insert_index(sorted_list, x)}

